#include <stdio.h>
#include <string.h>
#include <ctype.h>

/* Return the Soundex digit for a given (already upper‑case) character.
   Mapping:
        B, F, P, V           -> 1
        C, G, J, K, Q, S, X, Z -> 2
        D, T                -> 3
        L                   -> 4
        M, N                -> 5
        R                   -> 6
        all other characters -> 0
*/
static int soundex_digit(char c)
{
    switch (c) {
        case 'B': case 'F': case 'P': case 'V': return 1;
        case 'C': case 'G': case 'J': case 'K':
        case 'Q': case 'S': case 'X': case 'Z': return 2;
        case 'D': case 'T': return 3;
        case 'L': return 4;
        case 'M': case 'N': return 5;
        case 'R': return 6;
        default: return 0;
    }
}

/* Compute the Soundex code for the supplied string.
   The result is a 4‑character string: first letter (upper‑cased) followed
   by three digits, padded with '0' if necessary. */
static void soundex(const char *src, char out[5])
{
    char first = toupper((unsigned char)src[0]);
    out[0] = first;

    int prev = soundex_digit(first);
    int pos = 1;               /* position in out after the first letter */

    for (size_t i = 1; src[i] != '\0' && pos < 4; ++i) {
        int d = soundex_digit(toupper((unsigned char)src[i]));
        if (d != 0 && d != prev) {
            out[pos++] = (char)('0' + d);
        }
        prev = d;
    }

    while (pos < 4) {
        out[pos++] = '0';
    }
    out[4] = '\0';
}

int main(int argc, char *argv[])
{
    if (argc < 2 || argv[1][0] == '\0') {
        puts("EMPTY");
        return 0;
    }

    char result[5];
    soundex(argv[1], result);
    puts(result);
    return 0;
}
